create table products
(
    id                bigint generated by default as identity
        primary key,
    avg_rating        numeric(38, 2),
    created_at        timestamp(6)                  not null,
    description       text,
    name              text                          not null,
    popularity_score  numeric(38, 2)                not null
        constraint products_popularity_score_check
            check (popularity_score >= (0)::numeric),
    price             numeric(38, 2)                not null,
    stock_quantity    integer                       not null
        constraint products_stock_quantity_check
            check (stock_quantity >= 0),
    tags              text                          not null,
    total_cart_adds   integer      default 0        not null,
    total_clicks      integer      default 0        not null,
    category_id       bigint                        not null
        constraint fkog2rp4qthbtt2lfyhfo32lsw9
            references categories,
    additional_images jsonb,
    main_image_url    varchar(255) default ''::text not null
);

alter table products
    owner to postgres;

